ProjectALife.DialogueShards["scenes_any_21"] = {
{"s3_c04_humming_choir_048","any",2,"reg=worker|role=worker|day=5,300|mood=warm",{1,"I taught music, now I've got twenty kids humming with their mouths shut",2,"Why shut?",1,"Carries less, you can hear it in the room and not past the hall",2,"Sounds pretty",1,"Only choir I ever had that stayed quiet on purpose"}},
{"s3_c04_cornbread_night_049","any",3,"reg=worker,rescue|day=5,300|hour=18,23|mood=angry",{1,"Those children deserve the truth about their parents",2,"They're seven",3,"They already know, they're waiting to see if we'll lie",1,"Then I'll tell them",2,"Not tonight, tonight they had cornbread - let them have one night with cornbread"}},
{"s3_c04_same_list_050","any",1,"reg=rescue|role=rescue_clergy|day=7,300|hour=22,4|mood=sad",{1,"Well, Lord, same list as last night",1,"Hazel, the Mattox boys - everybody on that bridge, the little girl at the ball field",1,"I'll keep reading it till You tell me to quit, or till somebody else learns it by heart"}},
{"s3_hosp_001","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|day=0,30|mood=grim|world=vehicle,door,building,wind",{1,"Did you ever find out who propped the ambulance bay doors open that night?",2,"Does it matter?",1,"It matters to me, somebody wedged them with a mop bucket",2,"Then it was somebody who wanted a breeze, it was ninety-four degrees in that hallway"}},
{"s3_hosp_002","any",3,"reg=rescue|role=rescue_medical|mood=sad",{1,"I still pat my pocket for the narcotics keys every time I stand up",2,"You gave those keys to a deputy the second night",3,"And the deputy gave them to one of them, near as I could tell",1,"Point is my hand still checks, twelve years of checking"}},
{"s3_hosp_003","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|mood=grim",{1,"Found a pack of triage tags in the rig, red, yellow, green, black",2,"Burn the green ones for kindling",1,"Walking wounded is still a category",2,"Out here walking wounded just means wounded - keep the black ones, though",1,"Why?",2,"Saves writing"}},
{"s3_hosp_004","any",3,"reg=rescue|role=rescue_medical|day=0,21|mood=fear",{1,"The overhead said shelter in place, I remember thinking, where? It's a hospital",2,"Code Silver, then Code Black, then nobody on the overhead at all",3,"I heard the operator crying into the mic before she keyed off",1,"Doreen, she did the overhead for twenty years - Doreen"}},
{"s3_hosp_005","any",2,"reg=rescue|role=rescue_medical|tmp=seasoned",{1,"Amoxicillin, two bottles - Prednisone, one, insulin, none that's been kept cold",2,"What about the Hendricks boy? He's diabetic",1,"I know what the Hendricks boy is",2,"Okay, I was just asking",1,"Sorry, put him at the top of the list for the Rosewood run - that's all I have"}},
{"s3_hosp_006","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"Know what I miss? Bad hospital coffee, the kind that tasted like the pot",2,"Third floor cafeteria, burnt at six a.m. sharp",1,"I'd give a kidney for one cup",2,"Careful what you offer, I still remember how to take one out"}},
{"s3_hosp_007","any",2,"reg=rescue|role=rescue_medical|hour=0,5",{1,"When's the last time you slept four hours in a row?",2,"What day is it?",1,"{weekday}",2,"Then I have no idea, wake me if anybody's bleeding who wasn't bleeding before"}},
{"s3_hosp_008","any",3,"reg=rescue|role=rescue_medical|day=10,400",{1,"I heard somebody suggest fishing line when they ran out of sutures",2,"Was it clean?",3,"Nobody could tell me that",1,"Boiling something doesn't make it proper surgical equipment. I wouldn't put somebody's leg on that guess"}},
{"s3_hosp_009","any",1,"reg=rescue|role=rescue_medical,rescue_firefighter|mood=sad|world=vehicle,door",{1,"Box 14's still parked on Dixie Highway with the back doors hanging open",1,"Mike's clipboard is on the dash, I could see it through the windshield",1,"I didn't go get it - don't know why I even looked"}},
{"s3_hosp_010","any",2,"reg=rescue|role=rescue_medical|mood=angry",{1,"You gave the last bag of saline to the old man",2,"He was awake and asking for his wife, the other one wasn't going to wake up",1,"The other one was nineteen",2,"I know how old he was, I wrote it down"}},
{"s3_hosp_011","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"New ABCs for the student nurses, airway, breathing, chewing",2,"If it's chewing, skip straight to the end of the alphabet",1,"That's awful",2,"You're smiling",1,"I'm smiling like somebody who hasn't slept since {date}"}},
{"s3_hosp_012","any",3,"reg=rescue|role=rescue_medical|day=3,400|hour=4,11",{1,"Gave blood again this morning, that's three times",2,"You're gray as a sheet - sit down before you fall down",3,"We need another O negative - Army dog tags have the blood type stamped right on them",1,"Most of the Army boys I've seen lately are past donating"}},
{"s3_hosp_013","any",2,"reg=rescue|role=rescue_medical|mood=angry|world=stairs",{1,"The surgeon took his big silver car and left before they came up the stairs",2,"Maybe he had kids",1,"He had a boat, he talked about that boat every single morning on rounds",2,"Then I hope he's on it, and I hope it leaks a little"}},
{"s3_hosp_014","any",1,"reg=rescue|role=rescue_medical|mood=fear",{1,"Ninety-nine point one - that's nothing, that's the heat",1,"Scratch is clean, edges are pink, not red - pink is fine",1,"I'd tell a patient that, I'd tell a patient that and mean it, hahaha"}},
{"s3_hosp_015","any",2,"reg=rescue|role=rescue_medical|hour=4,11|mood=fear|world=generator",{1,"My pager went off at four this morning",2,"Pagers still work?",1,"Somebody's generator is still running the tower, I guess, it was the ER desk extension",2,"Nobody's at the ER desk",1,"Somebody's at the ER desk, that's why I took the battery out"}},
{"s3_hosp_016","any",3,"reg=rescue",{1,"Drug store in Riverside got cleaned out, whoever it was knew what they wanted",2,"Pain pills",1,"No, that's the thing, they left the pain pills - took every inhaler and all the baby formula",3,"Then that's a family - leave 'em be"}},
{"s3_hosp_017","any",2,"reg=rescue|role=rescue_medical|day=14,400|mood=warm",{1,"Mrs. Tackett's pressure is one-sixty over a hundred",2,"Without her pills it's only going to climb",1,"She wants to know if she can have coffee",2,"Tell her no, then give her half a cup, the woman's eighty-one and the world ended"}},
{"s3_hosp_018","any",1,"reg=rescue|role=rescue_medical,rescue_firefighter|hour=22,4|mood=sad",{1,"Medic 3 to dispatch",1,"Medic 3 to anybody on this channel",1,"Show us back in quarters, show us out of service - show us however you want"}},
{"s3_hosp_019","any",4,"reg=rescue|role=rescue_medical|world=door,stairs",{1,"Tell them about the stairwell",2,"No",3,"We held the fourth floor fire door with a gurney and two of us sitting on it",4,"For how long?",3,"Till the alarm quit, then Janet said she had to pee, and we laughed so hard they started pushing again",2,"I said no"}},
{"s3_hosp_020","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"I was three weeks into residency - three weeks",2,"Congratulations, you're chief of surgery now",1,"Chief of what?",2,"Of this picnic table"}},
{"s3_hosp_021","any",2,"reg=rescue|role=rescue_medical|mood=sad|world=cars",{1,"You worked the nursery, didn't you?",2,"Labor and delivery - nine years",1,"Did the babies get out?",2,"The Army loaded the incubators on the first trucks, that's what I decided happened"}},
{"s3_hosp_022","any",3,"reg=rescue|role=rescue_medical|day=7,400",{1,"Vet clinic in West Point has amoxicillin, same pills, says 'canine' on the label",2,"Same dose?",3,"It is if you do the math by body weight - I can do the math",1,"Then bring a pencil, I'll bring the bat"}},
{"s3_hosp_023","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"He says his pain's a ten",2,"On what scale?",1,"He says the old scale's broken and this is a new one - he's chatting with me though, so I wrote four"}},
{"s3_hosp_024","any",2,"reg=rescue|role=rescue_medical|mood=grim",{1,"If it's the hand, we take the hand, that's what I told him",2,"Did it work?",1,"He turned on the fourth day instead of the second",2,"So it didn't work",1,"It bought his wife two days, you go ask her if it worked"}},
{"s3_hosp_025","any",2,"reg=rescue|role=rescue_medical|mood=warm|world=vehicle",{1,"Somebody left a jar of honey on the tailgate with a note - 'for the nurses'",2,"Who?",1,"No name, handwriting like a second-grader's",2,"Put some on that burn on your arm, don't argue with me, my mamaw swore by it"}},
{"s3_hosp_026","any",3,"reg=rescue|role=rescue_medical|tmp=fresh,seasoned|day=0,7|world=fence,generator",{1,"They'll set up a field hospital, they always do - tents, generators, the whole setup",2,"Where?",1,"Fort Knox has an entire hospital on post",3,"Then why are they shooting along the fence line?",1,"I don't know, I'm going to keep saying tents until somebody gives me something better"}},
{"s3_hosp_027","any",2,"reg=rescue|role=rescue_medical|tmp=seasoned",{1,"You're writing on your arm again",2,"Times, when I gave the morphine, when he last woke up",1,"Nobody's going to audit your charting",2,"Somebody might, when this is over, somebody might want to know what we did with every milligram"}},
{"s3_hosp_028","any",1,"reg=rescue|role=rescue_medical|mood=sad",{1,"Last page I got from home was our number with 911 after it",1,"The kids did that all the time, for a spider - for who got the remote",1,"Got the machine when I called back, so I figured spider, and I finished my shift"}},
{"s3_hosp_029","any",2,"reg=rescue|role=rescue_medical|mood=calm",{1,"Somebody once suggested using a pressure canner as an autoclave",2,"Said a pressure and a time made it safe?",1,"Thirty minutes, they said. I wouldn't call instruments sterile on that alone",2,"Good. Cooking beans and preparing surgical instruments aren't the same job",1,"You tell Gary that. He thought knowing one meant knowing both"}},
{"s3_hosp_030","any",3,"reg=rescue|role=rescue_medical|mood=fear",{1,"Bed three's breathing changed",2,"Changed how?",1,"Slower, like he's forgetting how it goes",3,"Get the straps, and walk his wife out of the room first - gently"}},
{"s3_hosp_031","any",2,"reg=rescue|role=rescue_medical|day=5,400",{1,"Old man Pruitt's got a springhouse behind his place, stays cold all summer",2,"Cold enough for insulin?",1,"Cold enough to keep butter hard in July, I put a thermometer in there myself",2,"Then the insulin's taking the butter's shelf"}},
{"s3_hosp_032","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"What I want: a hot shower, a clean scrub top, and one patient who says thank you",2,"Two out of three are up in Louisville",1,"Which two?",2,"Doesn't matter, nobody's going to Louisville"}},
{"s3_hosp_033","any",2,"reg=rescue|role=rescue_medical|mood=sad",{1,"The whiteboard in the ER still had the shift roster up when we went back",2,"You went back in there?",1,"For the crash cart, my name was under charge nurse - somebody drew a smiley face next to it",2,"Probably Tina",1,"Yeah, probably Tina"}},
{"s3_hosp_034","any",2,"reg=rescue|role=rescue_medical|mood=grim|world=door,building",{1,"The morgue was the first place they came up from",2,"Don't",1,"I'm just saying, we put them all in one room - in the basement, with one door",2,"I said don't, I did intake down there"}},
{"s3_hosp_035","any",3,"reg=rescue|role=rescue_medical|mood=angry",{1,"Antibiotics go to wounds that are already infected, no more handing them out just in case",2,"If I don't treat that cut now, it'll be infected in three days",3,"And then it's on my list",1,"Then it goes on your list, I'm not handing out pills for maybe"}},
{"s3_hosp_036","any",2,"reg=rescue|role=rescue_medical|mood=warm",{1,"Little girl from the church bunch drew me a picture - it's me with a big red cross on my head",2,"On your head?",1,"She thought that's where it goes, it's in my scrub pocket"}},
{"s3_hosp_037","any",1,"reg=rescue|role=rescue_medical|tmp=seasoned|hour=1,5",{1,"Sit down for one minute - one, then check the dressings",1,"One more minute, the dressings aren't going anywhere",1,"Neither am I, looks like"}},
{"s3_hosp_038","any",2,"reg=rescue|role=rescue_medical|mood=grim",{1,"How much bleach is left?",2,"Two jugs, and whatever's in the laundry room at that motel",1,"Then hands get soap and prayer, bleach is for the tables",2,"And the floor where the Fraley kid was",1,"And the floor"}},
{"s3_hosp_039","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"Can you read this label? It's my own handwriting",2,"Says either penicillin or pencils",1,"Well, one of those will help"}},
{"s3_hosp_040","any",3,"reg=rescue|role=rescue_medical,rescue_firefighter|day=10,400",{1,"The Morrison girl's due in about three weeks",2,"Who here has delivered a baby?",3,"I've delivered calves",1,"That's more than me - you're up",3,"I want it on the record that I said calves"}},
{"s3_hosp_041","any",2,"reg=rescue|role=rescue_medical|mood=sad",{1,"I'm a nurse, I'm supposed to know what to do with a fever",2,"You do know",1,"I know what to do in a building with a pharmacy - out here I just watch the thermometer climb"}},
{"s3_hosp_042","any",2,"reg=rescue|role=rescue_medical|day=0,25|mood=angry",{1,"The Guard came through the clinic in March Ridge and took every IV bag we had",2,"Did they sign for them?",1,"A kid handed me a carbon copy, 'receipt of requisitioned materials'",2,"Keep it, when there's a county again, send them the bill"}},
{"s3_hosp_043","any",2,"reg=rescue|hour=22,4|mood=fear|world=door,wind",{1,"Did the side door just rattle?",2,"That's the wind",1,"There's no wind",2,"Then it's the building settling - go check, I'll hold the light"}},
{"s3_hosp_044","any",4,"reg=rescue|mood=funny|world=building",{1,"Who used the last roll of gauze on a splinter?",2,"It was a big splinter",3,"It was a porch",4,"I'm fine, by the way, thank you all for asking"}},
{"s3_hosp_045","any",2,"reg=rescue|role=rescue_medical|day=20,400|mood=funny",{1,"Tooth has to come out, I've got pliers and a bottle of bourbon",2,"Which one's for him?",1,"The pliers are for him"}},
{"s3_hosp_046","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|mood=warm",{1,"Remember that trucker on 31W the first night? With the cooler?",2,"Gave us every can of pop he had",1,"Wouldn't let me take his pressure, said go help somebody who needed it",2,"He needed it",1,"He did, he was still right about where to go"}},
{"s3_hosp_047","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|tmp=seasoned|world=vehicle,cars,building",{1,"Could we go back for the oxygen tanks? Basement, by the loading dock",2,"The loading dock is where the buses unloaded the first sick ones",1,"So that's a no",2,"That's a not without six people and a truck that starts on the first try"}},
{"s3_hosp_048","any",2,"reg=rescue|mood=warm",{1,"You've got blood in your hair",2,"Whose?",1,"Hold still, I've got a little water",2,"Nobody's washed my hair for me since I was six",1,"Well, don't get used to it, that was drinking water"}},
{"s3_hosp_049","any",2,"reg=rescue|role=rescue_medical|mood=grim|world=door",{1,"Somebody ought to check the nursing home in Rosewood",2,"Somebody did - last week",1,"And?",2,"And they painted a note on the door so nobody else would have to go in - that's all I'll say"}},
{"s3_hosp_050","any",1,"reg=rescue|role=rescue_medical|tmp=seasoned",{1,"Five hundred milligrams, every eight hours, for ten days",1,"Or five hundred, every eight hours, for three days - and hope",1,"Hope isn't on the label - I looked"}},
{"s3_hosp_051","any",2,"reg=rescue|role=rescue_medical|mood=funny",{1,"I've worn the same pair of gloves since Tuesday, I just wash them with my hands still in",2,"That's disgusting",1,"That's efficient"}},
{"s3_hosp_052","any",3,"reg=rescue|role=rescue_medical|mood=sad",{1,"He asked me for the whole bottle",2,"What did you tell him?",1,"I said let's talk about it in the morning",3,"Did you talk?",1,"He was asleep in the morning - just asleep, I checked twice"}},
{"s3_hosp_053","any",2,"reg=rescue|role=rescue_medical|mood=calm",{1,"Heard a woman on the CB last night asking about a burn on a toddler",2,"Did you answer her?",1,"Talked her through it for an hour, cool water, clean sheet, no butter",2,"She say where she was?",1,"Wouldn't - smart woman, said 'thank you, nurse' and went off the air"}},
{"s3_hosp_054","any",2,"reg=rescue|role=rescue_medical|day=10,400",{1,"What color were these scrubs to start with?",2,"Ceil blue",1,"These are not ceil blue",2,"They're ceil something"}},
{"s3_hosp_055","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|mood=funny",{1,"Remember when a 10-38 meant somebody was coming with lights?",2,"Now it means somebody's bleeding in the bed of your pickup",1,"Still counts as transport",2,"Put it on the run sheet"}},
{"s3_hosp_056","any",3,"reg=rescue|role=rescue_medical|mood=sad",{1,"The respiratory therapist, the one with the red glasses - what was her name?",2,"Carol - Carol something",3,"Carol Wimsatt, she taught me to intubate",1,"Carol Wimsatt - okay, I didn't want to lose that one"}},
{"s3_hosp_057","any",2,"reg=rescue|day=0,14|mood=fear",{1,"I heard men from the CDC were at the hospital the week before - before any of it",2,"Heard it from who?",1,"Security guard on nights",2,"Same security guard who saw a flying saucer over Ekron - twice"}},
{"s3_hosp_058","any",1,"reg=rescue|role=rescue_clergy|mood=calm",{1,"I was chaplain on the fourth floor, people would ask me to sit with them",1,"So I'd sit, that was most of the job, most nights - sit, and don't leave",1,"I'm still good at the not leaving"}},
{"s3_hosp_059","any",2,"reg=rescue|role=rescue_medical|tmp=seasoned",{1,"We've got more adult diapers than food",2,"Somebody raided the wrong aisle",1,"Somebody raided the right aisle, you try nursing a stroke patient in a hay barn without them"}},
{"s3_hosp_060","any",2,"reg=rescue|role=rescue_medical|mood=sad",{1,"Whose stethoscope is that? Somebody scratched initials on the bell",2,"R.M.P",1,"You know who that was?",2,"I know - leave it on the hook"}},
{"s3_hosp_061","any",3,"reg=rescue|mood=funny|world=fence",{1,"Visiting hours are over, sir",2,"Who are you talking to?",1,"Him, out by the fence - he's been standing there since noon",3,"Tell him the patient's in surgery, maybe he'll go wait in the lobby"}},
{"s3_hosp_062","any",2,"reg=rescue|role=rescue_medical,rescue_firefighter|hour=11,18",{1,"Three heat cases today, and one of them was me",2,"Drink",1,"I'm drinking - it's warm, it tastes like the jug",2,"It tastes like not passing out - drink"}},
{"s4_calls_biting_domestic_001","any",2,"reg=law|day=0,2|mood=fear",{1,"Third biting call since supper, dispatch keeps putting them out as domestics",2,"Lady on Dogwood said her husband bit the mailman, then the mailman bit him back",1,"That's not funny",2,"I'm not telling it funny, I'm reading you what I wrote down"}},
{"s4_calls_angel_dust_002","any",3,"reg=law|day=0,1|mood=calm",{1,"Sarge says it's angel dust, bad batch come down from Louisville",2,"Angel dust don't keep a man walking with four rounds in his chest",3,"Sarge also swore the Wildcats were going all the way this year",1,"Just write PCP in the report and let the state lab sort it out",2,"State lab's in Frankfort, good luck getting a body to Frankfort"}},
{"s4_calls_mutter_report_003","any",1,"reg=law|day=0,3|mood=grim",{1,"Subject was unresponsive to verbal commands, subject was unresponsive to the baton",1,"Subject was unresponsive to a whole lot of things, Lord",1,"How in the world am I supposed to word the rest of this?"}},
{"s4_calls_ems_wait_004","any",2,"reg=law|day=0,2|mood=angry",{1,"Forty minutes I waited on EMS at that trailer park - forty minutes holding pressure on a stranger's neck",2,"Every rig in the county's stacked up at the hospital",1,"Then say so on the air! Don't tell me they're en route when they're parked",2,"Nobody's saying anything on the air, that's the problem, right there"}},
{"s4_calls_loretta_console_005","any",2,"reg=law|day=0,3|mood=warm",{1,"Loretta's been on the console since six Friday morning, won't go home",2,"Her place is out past Ekron, maybe she knows something we don't",1,"Brought her a honey bun from the machine, she said thank you, baby, and keyed right back up"}},
{"s4_calls_six_rounds_006","any",2,"reg=law|day=0,2|mood=fear|world=road",{1,"Twelve years on the road and I never drew on anything but a sick dog",2,"How many times did you fire?",1,"Six, he kept coming, I counted every one, 'cause I figured there'd be a review board",2,"There's gonna be one - right? There's still gonna be a board",1,"Sure there is"}},
{"s4_calls_lawnmower_007","any",3,"reg=law|day=0,1|mood=funny",{1,"Know what I did Friday afternoon? Took a report on a stolen lawnmower",2,"Riding or push?",1,"Push, man was real tore up about it",3,"Bet he's gotten over it"}},
{"s4_calls_hospital_lot_008","any",3,"reg=law|day=1,3|mood=fear|world=vehicle",{1,"They want a car on the hospital lot around the clock - crowd control",2,"Crowd of what? Sick folks, or the families of sick folks?",3,"Both, and some of the sick ones don't stay in the beds",1,"We draw straws, I had it last night and I'm not going back without the shotgun"}},
{"s4_calls_failure_appear_009","any",2,"reg=law|day=0,2|mood=grim",{1,"Had a warrant in my shirt pocket Friday for Tommy Gaither - failure to appear",2,"You serve it?",1,"Found him in his front yard, down on top of his own beagle",2,"So he appeared",1,"Don't"}},
{"s4_calls_scanner_crowd_010","any",2,"reg=law|day=0,3|mood=angry|world=vehicle,cars",{1,"Half this county owns a scanner, every time we key up, forty pickups show up to watch",2,"Go to the car-to-car channel",1,"They got that one too, kid at the gas station on 31W read me back my own plate number"}},
{"s4_calls_back_seat_011","any",3,"reg=law|day=0,2|mood=fear|world=vehicle,door",{1,"Cuffed him behind the back, put him in my cage, and he chewed a hole in the seat",2,"That seat's vinyl",1,"I am aware what the seat is made of",3,"Where's he at now?",1,"Still in the car, I'm not opening that door till somebody tells me what he is"}},
{"s4_calls_mutter_eleven_012","any",1,"reg=law,swat|day=1,4|mood=sad",{1,"Told her I'd be home by eleven, that was Friday",1,"She's gonna give me hell for it - good, I want her to give me hell"}},
{"s4_calls_two_to_car_013","any",3,"reg=law|day=1,3|mood=calm|world=vehicle,cars",{1,"Sheriff's orders, nobody rides alone - two to a car, and the passenger carries the long gun",2,"We got fourteen cars and nine people who showed up for shift",1,"Then it's two to a car and five cars sit in the lot",3,"And the calls those five would've taken?",1,"They ring, you want that in writing, I'll put it in writing"}},
{"s4_calls_fellowship_hall_014","any",2,"reg=law|day=0,1|mood=grim",{1,"Call at the Baptist fellowship hall - church supper, a deacon went down, then got back up",2,"And?",1,"And the preacher went over to lay hands on him",2,"Did it take?",1,"No"}},
{"s4_calls_birdshot_015","any",2,"reg=law|day=1,3|mood=angry|world=vehicle",{1,"State police want every county to hold its own line and quit sending people up 31W",2,"Hold it with what? I got a cruiser with a bad alternator and a box of birdshot",1,"That's near word for word what I told the trooper - he said he had less"}},
{"s4_calls_burke_riverside_016","any",2,"reg=law|day=1,4|mood=sad",{1,"Burke asked to go check on his mother in Riverside - Sheriff told him no",2,"He went anyway",1,"Took his unit, keyed up once from the Riverside exit, said he was 10-23",2,"And?",1,"And I keep the radio on that channel"}},
{"s4_calls_nursing_home_017","any",3,"reg=law|day=1,3|mood=grim",{1,"Rosewood nursing home called, three residents are up and walking that shouldn't be able to",2,"Shouldn't be able to how?",1,"The nurse wouldn't say it on the phone",3,"I'll take it, my granny was in there eight years, I know every hall in that place"}},
{"s4_calls_nine_dogs_018","any",2,"reg=law|day=0,2|mood=funny",{1,"You notice every dog in {town} has been barking since Thursday night?",2,"I took nine noise complaints about it Friday - nine",1,"Should've taken the dog's statement"}},
{"s4_calls_door_marks_019","any",2,"reg=law|day=1,4|mood=calm|world=door",{1,"I'm taping every door we clear - X for somebody dead inside, one slash for empty",2,"Who's gonna read tape?",1,"Whoever comes after - the Army - the coroner, us, next week, when we forget which ones we did"}},
